import csv,math,collections,sys
qpath,mpath,apath,out=sys.argv[1:5]
def cor(a,b):
 ma=sum(a)/len(a);mb=sum(b)/len(b)
 va=sum((x-ma)**2 for x in a);vb=sum((y-mb)**2 for y in b)
 return sum((x-ma)*(y-mb) for x,y in zip(a,b))/math.sqrt(va*vb) if va and vb else 0.0
def collapse(x):
 if x in ("epidermal_neural1","epidermal_neural2"): return "epidermal_neural"
 return x
mc_counts=collections.defaultdict(collections.Counter)
with open(apath) as f:
 r=csv.DictReader(f,delimiter="\t")
 for x in r: mc_counts[x["metacell"]][collapse(x["cell_type"])]+=1
mc_label={m:c.most_common(1)[0][0] for m,c in mc_counts.items()}
with open(qpath) as f:
 r=csv.reader(f,delimiter="\t");h=next(r); qi={x:i for i,x in enumerate(h)}
 q={}
 for x in r:
  if x[0]:q[x[0]]=(float(x[qi["epidermal_neural"]]),float(x[qi["tailbud_neural"]]))
with open(mpath) as f:
 r=csv.reader(f,delimiter="\t");h=next(r)
 en=[i for i,m in enumerate(h) if mc_label.get(m)=="epidermal_neural"]
 tn=[i for i,m in enumerate(h) if mc_label.get(m)=="tailbud_neural"]
 data=[]
 for x in r:
  if x[0] not in q: continue
  try:
   a=sum(float(x[i]) for i in en)/len(en);b=sum(float(x[i]) for i in tn)/len(tn)
  except: continue
  data.append((x[0],a,b,q[x[0]][0],q[x[0]][1]))
def metrics(rows):
 re=[math.log1p(x[1]) for x in rows];rt=[math.log1p(x[2]) for x in rows]
 qe=[math.log1p(x[3]) for x in rows];qt=[math.log1p(x[4]) for x in rows]
 dref=[a-b for a,b in zip(re,rt)];dq=[a-b for a,b in zip(qe,qt)]
 return {"EN_to_ref_EN":cor(qe,re),"EN_to_ref_TN":cor(qe,rt),"TN_to_ref_EN":cor(qt,re),"TN_to_ref_TN":cor(qt,rt),
 "contrast_cor":cor(dq,dref),"matched_sum":cor(qe,re)+cor(qt,rt),"swapped_sum":cor(qe,rt)+cor(qt,re)}
ranked=sorted(data,key=lambda x:abs(math.log1p(x[1])-math.log1p(x[2])),reverse=True)
with open(out,"w") as f:
 f.write("subset\tmetric\tvalue\tdetail\n")
 f.write("qc\tmetacells_EN\t%d\tids=%s\n"%(len(en),",".join(h[i] for i in en)))
 f.write("qc\tmetacells_TN\t%d\tids=%s\n"%(len(tn),",".join(h[i] for i in tn)))
 f.write("qc\tmatched_genes\t%d\t\n"%len(data))
 for label,rows in [("all",data),("top100",ranked[:100]),("top250",ranked[:250]),("top500",ranked[:500]),("top1000",ranked[:1000])]:
  m=metrics(rows)
  for k,v in m.items(): f.write("%s\t%s\t%.10g\t\n"%(label,k,v))
 for x in ranked[:50]:
  f.write("marker\t%s\t%.10g\tref_TN=%.6g;query_EN=%.6g;query_TN=%.6g\n"%(x[0],math.log1p(x[1])-math.log1p(x[2]),x[2],x[3],x[4]))

